import { test } from 'node:test'
import assert from 'node:assert/strict'
import { RATING_SCALE, notchChange } from '../../src/ratings/notch.mjs'

const scale = ['AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-']

test('AC-1: notchChange("BBB+", "BB+") returns 3', () => {
  assert.strictEqual(notchChange('BBB+', 'BB+'), 3)
})

test('AC-2: notchChange("BB+", "BBB+") returns -3', () => {
  assert.strictEqual(notchChange('BB+', 'BBB+'), -3)
})

test('AC-3: same rating returns +0, not -0', () => {
  assert.strictEqual(notchChange('A', 'A'), 0)
  assert.strictEqual(Object.is(notchChange('A', 'A'), 0), true)
  assert.strictEqual(Object.is(notchChange('A', 'A'), -0), false)

  assert.strictEqual(notchChange('AAA', 'AAA'), 0)
  assert.strictEqual(Object.is(notchChange('AAA', 'AAA'), 0), true)

  assert.strictEqual(notchChange('CCC-', 'CCC-'), 0)
  assert.strictEqual(Object.is(notchChange('CCC-', 'CCC-'), 0), true)
})

test('AC-4: RATING_SCALE structure', () => {
  assert.deepStrictEqual(RATING_SCALE, scale)
  assert.strictEqual(RATING_SCALE.length, 19)
  assert.strictEqual(Array.isArray(RATING_SCALE), true)
  assert.strictEqual(Object.isFrozen(RATING_SCALE), true)
})

test('AC-5: RATING_SCALE is immutable', () => {
  assert.throws(() => {
    RATING_SCALE.push('D')
  }, TypeError)

  assert.throws(() => {
    RATING_SCALE[0] = 'X'
  }, TypeError)

  assert.throws(() => {
    RATING_SCALE.reverse()
  }, TypeError)

  // Verify scale is unchanged
  assert.strictEqual(RATING_SCALE[0], 'AAA')
  assert.strictEqual(RATING_SCALE.length, 19)
  assert.strictEqual(notchChange('BBB+', 'BB+'), 3)
})

test('AC-6: exports check', () => {
  const m = await import('../../src/ratings/notch.mjs')
  assert.strictEqual(typeof m.notchChange, 'function')
  assert.deepStrictEqual(m.RATING_SCALE, scale)
  assert.strictEqual(m.RATING_SCALE === RATING_SCALE, true)
  assert.strictEqual('default' in m, false)
})

test('AC-7: all 361 pairs produce correct results', () => {
  for (let i = 0; i < 19; i++) {
    for (let j = 0; j < 19; j++) {
      const result = notchChange(scale[i], scale[j])
      assert.strictEqual(result, j - i, `notchChange(${scale[i]}, ${scale[j]})`)
      assert.strictEqual(typeof result, 'number')
      assert.strictEqual(Number.isInteger(result), true)
    }
  }
})

test('AC-7: concrete table entries', () => {
  assert.strictEqual(notchChange('AAA', 'CCC-'), 18)
  assert.strictEqual(notchChange('CCC-', 'AAA'), -18)
  assert.strictEqual(notchChange('AA+', 'AA'), 1)
  assert.strictEqual(notchChange('A-', 'BBB+'), 1)
  assert.strictEqual(notchChange('BBB-', 'BB+'), 1)
  assert.strictEqual(notchChange('BB+', 'BBB-'), -1)
  assert.strictEqual(notchChange('B-', 'CCC+'), 1)
  assert.strictEqual(notchChange('AAA', 'AA+'), 1)
  assert.strictEqual(notchChange('CCC', 'CCC-'), 1)
  assert.strictEqual(notchChange('A', 'BBB'), 3)
})

test('AC-8: case insensitivity', () => {
  assert.strictEqual(notchChange('bbb+', 'bb+'), 3)
  assert.strictEqual(notchChange('Bb+', 'bBb+'), -3)
  assert.strictEqual(notchChange('aaa', 'ccc-'), 18)
  assert.strictEqual(notchChange('a', 'A'), 0)
})

test('AC-9: trim whitespace (space, tab, newline, NBSP, BOM)', () => {
  assert.strictEqual(notchChange(' BBB+ ', 'BB+'), 3)
  assert.strictEqual(notchChange('\tbb+\n', '  BBB+'), -3)
  assert.strictEqual(notchChange(' A ', 'A'), 0)
  // NBSP (U+00A0) should be trimmed
  assert.strictEqual(notchChange(' A ', 'A'), 0)
  // BOM (U+FEFF) should be trimmed
  assert.strictEqual(notchChange('﻿AAA', 'AA+'), 1)
})

test('AC-10: zero-width space inside rating throws', () => {
  assert.throws(() => {
    notchChange('​A', 'A')
  }, RangeError)

  assert.throws(() => {
    notchChange('BBB +', 'A')
  }, RangeError)

  assert.throws(() => {
    notchChange('A', 'B B')
  }, RangeError)
})

test('AC-11: unknown strings throw RangeError', () => {
  const unknownRatings = ['D', 'CC', 'C', 'SD', 'NR', 'WD', 'AAA+', 'A++', 'Baa1', 'BBB+ (neg)', 'BBB+u', 'BBB−', 'BBB‐']

  for (const rating of unknownRatings) {
    assert.throws(() => {
      notchChange(rating, 'A')
    }, RangeError, `${rating} as previous`)
    assert.throws(() => {
      notchChange('A', rating)
    }, RangeError, `${rating} as current`)
  }
})

test('AC-12: empty or whitespace-only strings throw', () => {
  const empty = ['', '   ', '\t\n', ' ']

  for (const val of empty) {
    assert.throws(() => {
      notchChange(val, 'A')
    }, RangeError, `'${val}' as previous`)
    assert.throws(() => {
      notchChange('A', val)
    }, RangeError, `'${val}' as current`)
  }
})

test('AC-13: non-strings throw RangeError', () => {
  const nonStrings = [undefined, null, 3, 0, NaN, true, {}, [], ['A'], new String('A'), new String('BBB+'), Symbol('A'), 10n, () => 'A']

  for (const val of nonStrings) {
    assert.throws(() => {
      notchChange(val, 'A')
    }, RangeError, `${typeof val} as previous`)
    assert.throws(() => {
      notchChange('A', val)
    }, RangeError, `${typeof val} as current`)
  }

  // Missing arguments
  assert.throws(() => {
    notchChange()
  }, RangeError)

  assert.throws(() => {
    notchChange('A')
  }, RangeError)
})

test('AC-14: both arguments invalid', () => {
  assert.throws(() => {
    notchChange('X', null)
  }, RangeError)

  assert.throws(() => {
    notchChange('', '')
  }, RangeError)
})

test('AC-15: safe error messages', () => {
  // Object.create(null) as previous
  assert.throws(() => {
    notchChange(Object.create(null), 'A')
  }, RangeError)

  // Symbol as current
  assert.throws(() => {
    notchChange('A', Symbol('x'))
  }, RangeError)

  // Object with throwing toString
  assert.throws(() => {
    notchChange({ toString() { throw new Error('boom') } }, 'A')
  }, RangeError)

  // Message checks
  let error
  try {
    notchChange('D', 'A')
  } catch (e) {
    error = e
  }
  assert(error instanceof RangeError)
  assert(typeof error.message === 'string')
  assert(error.message.length > 0)
  assert(error.message.includes('previous'))

  try {
    notchChange('A', 'D')
  } catch (e) {
    error = e
  }
  assert(error instanceof RangeError)
  assert(typeof error.message === 'string')
  assert(error.message.length > 0)
  assert(error.message.includes('current'))
})

test('AC-16: extra arguments are ignored', () => {
  assert.strictEqual(notchChange('A', 'A', 'x'), 0)
  assert.strictEqual(notchChange('BBB+', 'BB+', 'extra', 'args'), 3)
})

